<?php
session_start();if(!isset($_SESSION['username'],$_SESSION['role'])||$_SESSION['role']!=='instructor'){header('Location: /authenication/login/login.php');exit();}
require_once(__DIR__.'/../../Database/db/db.php');require_once(__DIR__.'/../../includes/csrf/csrf.php');$pdo=get_db();$token=instructor_csrf_token();$instructorId=(int)($_SESSION['user_id']??0);$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!instructor_csrf_valid($_POST['csrf_token']??''))$error='Your session expired. Refresh and try again.';
 else{$courseId=(int)($_POST['course_id']??0);$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');$dueDate=trim($_POST['due_date']??'');$owns=$pdo->prepare('SELECT id FROM courses WHERE id=? AND instructor_id=?');$owns->execute([$courseId,$instructorId]);if(!$owns->fetch())$error='Choose one of your courses.';elseif($title==='')$error='Assignment title is required.';elseif($dueDate!==''&&strtotime($dueDate)===false)$error='Enter a valid due date.';else{$insert=$pdo->prepare('INSERT INTO assignments(course_id,title,description,due_date) VALUES(?,?,?,?)');$insert->execute([$courseId,$title,$description,$dueDate?:null]);$notice='Assignment created successfully.';}}
}
$q=$pdo->prepare('SELECT id,title FROM courses WHERE instructor_id=? ORDER BY title');$q->execute([$instructorId]);$courses=$q->fetchAll();
$q=$pdo->prepare('SELECT a.title,a.due_date,c.title AS course_title,COUNT(s.id) AS submissions FROM assignments a JOIN courses c ON c.id=a.course_id LEFT JOIN assignment_submissions s ON s.assignment_id=a.id WHERE c.instructor_id=? GROUP BY a.id ORDER BY a.created_at DESC LIMIT 8');$q->execute([$instructorId]);$assignments=$q->fetchAll();
include(__DIR__.'/../../includes/header/header.php');include(__DIR__.'/../../includes/navbar/navbar.php');include(__DIR__.'/../../includes/sidebar/sidebar.php');
