><thead><tr><th>Assignment</th><th>Course</th><th>Due date</th><th>Submissions</th></tr></thead><tbody><?php if(!$assignments):?><tr><td colspan="4" class="text-center text-muted py-4">No assignments yet.</td></tr><?php endif;?><?php foreach($assignments as $a):?><tr><td><strong><?=htmlspecialchars($a['title'],ENT_QUOTES,'UTF-8')?></strong></td><td><?=htmlspecialchars($a['course_title'],ENT_QUOTES,'UTF-8')?></td><td><?=$a['due_date']?htmlspecialchars(date('M j, Y',strtotime($a['due_date'])),ENT_QUOTES,'UTF-8'):'No due date'?></td><td><?=number_format((int)$a['submissions'])?></td></tr><?php endforeach;?></tbody></table></div></section></div></div></div></main><?php include(__DIR__.'/../../includes/footer/footer.php');?>
